package pl.nclean.crm.costs;

import java.time.*;
import java.util.*;
import java.security.Principal;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.*;
import org.springframework.web.multipart.MultipartFile;
import pl.nclean.crm.dashboard.DashboardService;
import pl.nclean.crm.fuel.*;
import pl.nclean.crm.records.ChemistryService;

@Controller
public class CostController {
    private final CostService costs;private final DashboardService dashboard;private final FuelJournalService fuel;private final ReceiptService receipts;private final ChemistryService chemistry;
    public CostController(CostService costs,DashboardService dashboard,FuelJournalService fuel,ReceiptService receipts,ChemistryService chemistry){this.costs=costs;this.dashboard=dashboard;this.fuel=fuel;this.receipts=receipts;this.chemistry=chemistry;}
    public static final Map<String,String> MONTHLY=Map.of("MARKETING","Marketing","LEASE","Leasing","INSURANCE","Ubezpieczenie","ACCOUNTING","Księgowość","PHONE","Telefon","SOFTWARE","Oprogramowanie","OTHER","Inne");
    @GetMapping("/costs") String page(@RequestParam(required=false) YearMonth month,@RequestParam(defaultValue="month") String range,@RequestParam(defaultValue="overview") String view,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="false") boolean cancelled,@RequestParam(defaultValue="0") int page,Model m){
        if(!Set.of("month","year").contains(range))throw new IllegalArgumentException("Wybierz miesiąc lub rok.");var selected=month==null?YearMonth.from(DashboardService.today()):month;DashboardService.period(selected.atDay(1),"day");LocalDate start=range.equals("year")?selected.atDay(1).withDayOfYear(1):selected.atDay(1),end=range.equals("year")?start.withMonth(12).withDayOfMonth(31):selected.atEndOfMonth();
        var all=costs.entries(start,end,view,q,cancelled,page);m.addAttribute("entries",all.subList(0,Math.min(50,all.size())));m.addAttribute("more",all.size()>50);m.addAttribute("page",page);m.addAttribute("q",q);m.addAttribute("cancelled",cancelled);m.addAttribute("month",selected);m.addAttribute("range",range);m.addAttribute("view",view);m.addAttribute("start",start);m.addAttribute("end",end);m.addAttribute("previous",range.equals("year")?selected.minusYears(1):selected.minusMonths(1));m.addAttribute("next",range.equals("year")?selected.plusYears(1):selected.plusMonths(1));
        m.addAttribute("totals",costs.totals(start,end));m.addAttribute("assets",costs.assets());m.addAttribute("usage",view.equals("chemistry")?costs.usage(start,end):List.of());m.addAttribute("zeros",view.equals("chemistry")?costs.zeroUsage(start,end):List.of());m.addAttribute("categories",CostService.CATEGORIES);var recognised=java.math.BigDecimal.ZERO;boolean complete=true;for(var ym=YearMonth.from(start);!ym.isAfter(YearMonth.from(end));ym=ym.plusMonths(1)){var sum=dashboard.summary(ym.atDay(1),"month","actual");recognised=recognised.add(sum.costs());complete&=sum.complete();}m.addAttribute("recognised",recognised);m.addAttribute("costsComplete",complete);m.addAttribute("today",DashboardService.today());return "costs/index";
    }
    @GetMapping("/costs/editor") String editor(@RequestParam(required=false) Long id,@RequestParam(required=false) LocalDate date,@RequestParam(required=false) Long asset,Model m){var day=date==null?DashboardService.today():date;DashboardService.period(day,"day");var entry=new LinkedHashMap<String,Object>();if(id!=null)entry.putAll(costs.entry(id));else{entry.put("version",0);entry.put("request_token",UUID.randomUUID());entry.put("spent_on",day);entry.put("category",asset==null?"CAR_REPAIR":"EQUIPMENT_SERVICE");entry.put("asset_id",asset);entry.put("effect","OPERATING");entry.put("quantity",null);}m.addAttribute("expense",entry);m.addAttribute("assets",costs.assets());m.addAttribute("chemicals",chemistry.materials());m.addAttribute("categories",CostService.CATEGORIES);m.addAttribute("monthlyCategories",MONTHLY);if(id!=null)m.addAttribute("audit",costs.audit(id));else m.addAttribute("audit",List.of());return "costs/editor";}
    @PostMapping("/costs") @ResponseBody ResponseEntity<?> save(@RequestParam Map<String,String> p,Principal actor){try{return ResponseEntity.ok(Map.of("saved",true,"id",costs.save(p,actor.getName())));}catch(IllegalArgumentException|DateTimeException ex){return error(ex);}}
    @PostMapping("/costs/{id}/cancel") @ResponseBody ResponseEntity<?> cancel(@PathVariable long id,@RequestParam long version,@RequestParam String reason,Principal actor){try{costs.cancel(id,version,reason,actor.getName());return ResponseEntity.ok(Map.of("saved",true));}catch(IllegalArgumentException ex){return error(ex);}}
    @PostMapping("/costs/fuel/{id}/cancel") @ResponseBody ResponseEntity<?> cancelFuel(@PathVariable long id,@RequestParam long version,@RequestParam String reason,Principal actor){try{fuel.cancelPurchase(id,version,reason,actor.getName());return ResponseEntity.ok(Map.of("saved",true));}catch(IllegalArgumentException ex){return error(ex);}}
    @GetMapping("/costs/equipment/{id}") String equipment(@PathVariable long id,@RequestParam(required=false) YearMonth month,@RequestParam(defaultValue="month") String range,@RequestParam(defaultValue="equipment") String view,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="false") boolean cancelled,Model m){if(!Set.of("month","year").contains(range)||!Set.of("overview","car","equipment","chemistry","fixed","all").contains(view)||q.length()>120)throw new IllegalArgumentException("Sprawdź filtr.");var selected=month==null?YearMonth.from(DashboardService.today()):month;DashboardService.period(selected.atDay(1),"day");m.addAttribute("month",selected);m.addAttribute("range",range);m.addAttribute("view",view);m.addAttribute("q",q);m.addAttribute("cancelled",cancelled);m.addAttribute("asset",costs.asset(id));var history=costs.assetHistory(id);history.forEach(e->e.put("source","EXPENSE"));m.addAttribute("history",history);m.addAttribute("summary",costs.assets().stream().filter(a->((Number)a.get("id")).longValue()==id).findFirst().orElseThrow());m.addAttribute("categories",CostService.CATEGORIES);return "costs/equipment";}
    @PostMapping("/costs/equipment/{id}") @ResponseBody ResponseEntity<?> equipmentSave(@PathVariable long id,@RequestParam long version,@RequestParam Map<String,String> p,Principal actor){try{costs.editAsset(id,version,p,actor.getName());return ResponseEntity.ok(Map.of("saved",true));}catch(IllegalArgumentException|DateTimeException ex){return error(ex);}}
    @PostMapping("/costs/receipts") @ResponseBody ResponseEntity<?> upload(@RequestParam("image") MultipartFile image){try{var id=receipts.upload(image);return ResponseEntity.ok(Map.of("id",id,"url","/fuel/receipts/"+id));}catch(IllegalArgumentException ex){return error(ex);}}
    private static ResponseEntity<?> error(Exception ex){return ResponseEntity.badRequest().body(Map.of("message",ex.getMessage()==null?"Sprawdź pola formularza.":ex.getMessage()));}
    @ExceptionHandler({IllegalArgumentException.class,DateTimeException.class}) @ResponseStatus(HttpStatus.BAD_REQUEST) String invalid(Model m){m.addAttribute("message","Sprawdź okres i dane wydatku.");return "records/error";}
}
